import { AdminApp, type AdminBranding } from "@emdash-cms/admin/app";
import { loadMessages } from "@emdash-cms/admin/locales";
import type { Messages } from "@lingui/core";
import { lazy, Suspense, useMemo } from "react";
// @ts-ignore - virtual module generated by integration
import { loadPluginAdmins } from "virtual:emdash/admin-loader";
// @ts-ignore - virtual module generated by integration
import { authProviders } from "virtual:emdash/auth-providers";

interface AdminWrapperProps {
	locale: string;
	messages?: Messages;
	/** Configured admin white-label branding (logo, site name), read server-side from `admin.astro`. */
	adminBranding?: AdminBranding;
}

export default function AdminWrapper(props: AdminWrapperProps) {
	const PluginAdminApp = useMemo(
		() =>
			lazy(async () => {
				const [{ pluginAdmins }, messages] = await Promise.all([
					loadPluginAdmins(),
					props.messages ? Promise.resolve(props.messages) : loadMessages(props.locale),
				]);
				return {
					default: () => (
						<AdminApp
							pluginAdmins={pluginAdmins}
							authProviders={authProviders}
							adminBranding={props.adminBranding}
							locale={props.locale}
							messages={messages}
						/>
					),
				};
			}),
		[props.locale, props.messages, props.adminBranding],
	);

	return (
		<Suspense fallback={null}>
			<PluginAdminApp />
		</Suspense>
	);
}
